{-| @Backend.Runtime.Kernel.Sha2 — SHA-256 and SHA-512 with incremental states. -}
module Pudu.Backend.Runtime.Kernel.Sha2 (sha2KernelParts) where

import Data.Text (Text)

{-| Each part: its name, the parts it needs, and its lines. -}
sha2KernelParts :: [(Text, [Text], [Text])]
sha2KernelParts =
  [ ("rotr32", [],
      [ "static inline uint32_t pudu_rotr32(uint32_t word, int count) { return (word >> count) | (word << (32 - count)); }"
      ])
  , ("rotr64", [],
      [ "static inline uint64_t pudu_rotr64(uint64_t word, int count) { return (word >> count) | (word << (64 - count)); }"
      ])
  , ("sha256", ["rotr32"],
      [ "/* SHA-256 over bytes fed in any number of pieces. */"
      , "typedef struct { uint32_t state[8]; uint64_t length; unsigned char block[64]; size_t held; } pudu_sha256;"
      , "static void pudu_sha256_block(pudu_sha256 *hash, const unsigned char *block) {"
      , "  static const uint32_t k[64] = {"
      , "    UINT32_C(0x428a2f98), UINT32_C(0x71374491), UINT32_C(0xb5c0fbcf), UINT32_C(0xe9b5dba5), UINT32_C(0x3956c25b), UINT32_C(0x59f111f1),"
      , "    UINT32_C(0x923f82a4), UINT32_C(0xab1c5ed5), UINT32_C(0xd807aa98), UINT32_C(0x12835b01), UINT32_C(0x243185be), UINT32_C(0x550c7dc3),"
      , "    UINT32_C(0x72be5d74), UINT32_C(0x80deb1fe), UINT32_C(0x9bdc06a7), UINT32_C(0xc19bf174), UINT32_C(0xe49b69c1), UINT32_C(0xefbe4786),"
      , "    UINT32_C(0x0fc19dc6), UINT32_C(0x240ca1cc), UINT32_C(0x2de92c6f), UINT32_C(0x4a7484aa), UINT32_C(0x5cb0a9dc), UINT32_C(0x76f988da),"
      , "    UINT32_C(0x983e5152), UINT32_C(0xa831c66d), UINT32_C(0xb00327c8), UINT32_C(0xbf597fc7), UINT32_C(0xc6e00bf3), UINT32_C(0xd5a79147),"
      , "    UINT32_C(0x06ca6351), UINT32_C(0x14292967), UINT32_C(0x27b70a85), UINT32_C(0x2e1b2138), UINT32_C(0x4d2c6dfc), UINT32_C(0x53380d13),"
      , "    UINT32_C(0x650a7354), UINT32_C(0x766a0abb), UINT32_C(0x81c2c92e), UINT32_C(0x92722c85), UINT32_C(0xa2bfe8a1), UINT32_C(0xa81a664b),"
      , "    UINT32_C(0xc24b8b70), UINT32_C(0xc76c51a3), UINT32_C(0xd192e819), UINT32_C(0xd6990624), UINT32_C(0xf40e3585), UINT32_C(0x106aa070),"
      , "    UINT32_C(0x19a4c116), UINT32_C(0x1e376c08), UINT32_C(0x2748774c), UINT32_C(0x34b0bcb5), UINT32_C(0x391c0cb3), UINT32_C(0x4ed8aa4a),"
      , "    UINT32_C(0x5b9cca4f), UINT32_C(0x682e6ff3), UINT32_C(0x748f82ee), UINT32_C(0x78a5636f), UINT32_C(0x84c87814), UINT32_C(0x8cc70208),"
      , "    UINT32_C(0x90befffa), UINT32_C(0xa4506ceb), UINT32_C(0xbef9a3f7), UINT32_C(0xc67178f2) };"
      , "  uint32_t w[64], v[8];"
      , "  for (int i = 0; i < 16; ++i)"
      , "    w[i] = (uint32_t)block[4 * i] << 24 | (uint32_t)block[4 * i + 1] << 16 | (uint32_t)block[4 * i + 2] << 8 | block[4 * i + 3];"
      , "  for (int i = 16; i < 64; ++i)"
      , "    w[i] = w[i - 16] + (pudu_rotr32(w[i - 15], 7) ^ pudu_rotr32(w[i - 15], 18) ^ (w[i - 15] >> 3))"
      , "      + w[i - 7] + (pudu_rotr32(w[i - 2], 17) ^ pudu_rotr32(w[i - 2], 19) ^ (w[i - 2] >> 10));"
      , "  memcpy(v, hash->state, sizeof v);"
      , "  for (int i = 0; i < 64; ++i) {"
      , "    uint32_t first = v[7] + (pudu_rotr32(v[4], 6) ^ pudu_rotr32(v[4], 11) ^ pudu_rotr32(v[4], 25)) + ((v[4] & v[5]) ^ (~v[4] & v[6])) + k[i] + w[i];"
      , "    uint32_t second = (pudu_rotr32(v[0], 2) ^ pudu_rotr32(v[0], 13) ^ pudu_rotr32(v[0], 22)) + ((v[0] & v[1]) ^ (v[0] & v[2]) ^ (v[1] & v[2]));"
      , "    memmove(v + 1, v, 7 * sizeof v[0]);"
      , "    v[4] += first;"
      , "    v[0] = first + second;"
      , "  }"
      , "  for (int i = 0; i < 8; ++i) hash->state[i] += v[i];"
      , "}"
      , "static void pudu_sha256_start(pudu_sha256 *hash) {"
      , "  static const uint32_t start[8] = { UINT32_C(0x6a09e667), UINT32_C(0xbb67ae85), UINT32_C(0x3c6ef372), UINT32_C(0xa54ff53a), UINT32_C(0x510e527f), UINT32_C(0x9b05688c), UINT32_C(0x1f83d9ab), UINT32_C(0x5be0cd19) };"
      , "  memcpy(hash->state, start, sizeof start);"
      , "  hash->length = 0;"
      , "  hash->held = 0;"
      , "}"
      , "static void pudu_sha256_feed(pudu_sha256 *hash, const unsigned char *bytes, size_t length) {"
      , "  hash->length += length;"
      , "  while (length != 0) {"
      , "    size_t take = 64 - hash->held < length ? 64 - hash->held : length;"
      , "    memcpy(hash->block + hash->held, bytes, take);"
      , "    hash->held += take;"
      , "    bytes += take;"
      , "    length -= take;"
      , "    if (hash->held == 64) { pudu_sha256_block(hash, hash->block); hash->held = 0; }"
      , "  }"
      , "}"
      , "static void pudu_sha256_finish(pudu_sha256 *hash, unsigned char *digest) {"
      , "  unsigned char pad[72] = {0x80};"
      , "  uint64_t bits = hash->length * 8;"
      , "  size_t fill = (hash->held < 56 ? 56 : 120) - hash->held;"
      , "  for (int i = 0; i < 8; ++i) pad[fill + i] = (unsigned char)(bits >> (56 - 8 * i));"
      , "  pudu_sha256_feed(hash, pad, fill + 8);"
      , "  for (int i = 0; i < 32; ++i) digest[i] = (unsigned char)(hash->state[i / 4] >> (24 - 8 * (i % 4)));"
      , "}"
      ])
  , ("sha256_of", ["sha256", "kernel_pack"],
      [ "static pudu_box *pudu_sha256_of(pudu_box *message) {"
      , "  pudu_sha256 hash;"
      , "  unsigned char digest[32];"
      , "  pudu_sha256_start(&hash);"
      , "  pudu_sha256_feed(&hash, message->fields[0].text.bytes, message->fields[0].text.length);"
      , "  pudu_sha256_finish(&hash, digest);"
      , "  return pudu_kernel_pack(digest, sizeof digest);"
      , "}"
      ])
  , ("sha512", ["rotr64"],
