      , "  for (int i = 0; i < 64; ++i) digest[i] = (unsigned char)(hash->state[i / 8] >> (56 - 8 * (i % 8)));"
      , "}"
      ])
  , ("sha512_of", ["sha512", "kernel_pack"],
